(window.__qhadithX=window.__qhadithX||{})[31]={"5":[{"c":"Al-Adab Al-Mufrad","r":"Book 33, Hadith 786","u":"https://quranx.com/Hadith/Adab/English/Book-33/Hadith-786","x":"Ibn 'Abbas said about \"There are some people who trade in distracting tales\" (31:5) that it means singing and things like it.","ar":"حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، قَالَ‏:‏ أَخْبَرَنَا خَالِدُ بْنُ عَبْدِ اللهِ، قَالَ‏:‏ أَخْبَرَنَا عَطَاءُ بْنُ السَّائِبِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ‏}‏، قَالَ‏:‏ الْغِنَاءُ وَأَشْبَاهُهُ‏.‏","v":[]}],"6":[{"c":"Jami` at-Tirmidhi","r":"Volume 3, Book 12, Hadith 1282","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-3/Book-12/Hadith-1282","x":"Narrated Abu Umamah:\n\nThat the Messenger of Allah (ﷺ) said: \"Do not sell the (slave) female singers, not purchase them, nor teach them (to sing). And there is no good in trading in them, and their prices are unlawful. It was about the likes of this that this Ayah was revealed: And among mankind is he who purchases idle talk to divert from the way of Allah.\" [He said:] There is narration about this from 'Umar bin Al-Khattab. [Abu 'Eisa said:] We only know of the Hadith of Abu Umamah, like this, from this route. Some of the people of knowledge have criticized 'Ali bin Yazid (one of the narrators) and graded him weak, and he is from Ash-Sham.","ar":"حَدَّثَنَا قُتَيْبَةُ، أَخْبَرَنَا بَكْرُ بْنُ مُضَرَ، عَنْ عُبَيْدِ اللَّهِ بْنِ زَحْرٍ، عَنْ عَلِيِّ بْنِ يَزِيدَ، عَنِ الْقَاسِمِ، عَنْ أَبِي أُمَامَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ تَبِيعُوا الْقَيْنَاتِ وَلاَ تَشْتَرُوهُنَّ وَلاَ تُعَلِّمُوهُنَّ وَلاَ خَيْرَ فِي تِجَارَةٍ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ فِي مِثْلِ هَذَا أُنْزِلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ ‏)‏ إِلَى آخِرِ الآيَةِ ‏\"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عُمَرَ بْنِ الْخَطَّابِ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي أُمَامَةَ إِنَّمَا نَعْرِفُهُ مِثْلَ هَذَا مِنْ هَذَا الْوَجْهِ ‏.‏ وَقَدْ تَكَلَّمَ بَعْضُ أَهْلِ الْعِلْمِ فِي عَلِيِّ بْنِ يَزِيدَ وَضَعَّفَهُ وَهُوَ شَامِيٌّ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3195","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3195","x":"Narrated Abu Umamah:\n\nthat the Messenger of Allah (ﷺ) said: \"Do not sell the female singers, nor purchase them, nor teach them (to sing). And there is no good in trade in them, and their prices are unlawful. It was about the likes of this that this Ayah was revealed: 'And among mankind is he who purchases idle talk to divert from the way of Allah (31:6).'\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا بَكْرُ بْنُ مُضَرَ، عَنْ عُبَيْدِ اللَّهِ بْنِ زَحْرٍ، عَنْ عَلِيِّ بْنِ يَزِيدَ، عَنِ الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ، وَهُوَ عَبْدُ الرَّحْمَنِ مَوْلَى عَبْدِ الرَّحْمَنِ عَنْ أَبِي أُمَامَةَ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ تَبِيعُوا الْقَيْنَاتِ وَلاَ تَشْتَرُوهُنَّ وَلاَ تُعَلِّمُوهُنَّ وَلاَ خَيْرَ فِي تِجَارَةٍ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ ‏\"‏ ‏.‏ فِي مِثْلِ ذَلِكَ أُنْزِلَتْ عَلَيْهِ هَذِهِ الآيَةُ ‏:‏ ‏(‏ومِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ ‏)‏ إِلَى آخِرِ الآيَةِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ إِنَّمَا يُرْوَى مِنْ حَدِيثِ الْقَاسِمِ عَنْ أَبِي أُمَامَةَ ‏.‏ وَالْقَاسِمُ ثِقَةٌ وَعَلِيُّ بْنُ يَزِيدَ يُضَعَّفُ فِي الْحَدِيثِ قَالَ سَمِعْتُ مُحَمَّدَ بْنَ إِسْمَاعِيلَ يَقُولُ الْقَاسِمُ ثِقَةٌ وَعَلِيُّ بْنُ يَزِيدَ يُضَعَّفُ ‏.‏","v":[]}],"13":[{"c":"Sahih Bukhari","r":"Hadith 32","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-32","x":"Narrated 'Abdullah:\n\nWhen the following Verse was revealed: \"It is those who believe and confuse not their belief with wrong (worshipping others besides Allah.)\" (6:83), the companions of Allah's Messenger (ﷺ) asked, \"Who is amongst us who had not done injustice (wrong)?\" Allah revealed: \"No doubt, joining others in worship with Allah is a great injustice (wrong) indeed.\" (31.13)","ar":"حَدَّثَنَا أَبُو الْوَلِيدِ، قَالَ حَدَّثَنَا شُعْبَةُ، ح‏.‏ قَالَ وَحَدَّثَنِي بِشْرٌ، قَالَ حَدَّثَنَا مُحَمَّدٌ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَمَّا نَزَلَتِ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ قَالَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم أَيُّنَا لَمْ يَظْلِمْ فَأَنْزَلَ اللَّهُ ‏{‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3360","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3360","x":"Narrated `Abdullah:\n\nWhen the Verse:--\"It is those who believe and do not confuse their belief with wrong ( i.e. joining others in worship with Allah\" (6.83) was revealed, we said, \"O Allah's Messenger (ﷺ)! Who is there amongst us who has not done wrong to himself?\" He replied, \"It is not as you say, for 'wrong' in the Verse and 'do not confuse their belief, with wrong means 'SHIRK' (i.e. joining others in worship with Allah). Haven't you heard Luqman's saying to his son, 'O my son! Join not others in worship with Allah, verily joining others in worship with Allah is a great wrong indeed.\" (31.13)","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، قَالَ حَدَّثَنِي إِبْرَاهِيمُ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتِ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ قُلْنَا يَا رَسُولَ اللَّهِ أَيُّنَا لاَ يَظْلِمُ نَفْسَهُ قَالَ ‏\"‏ لَيْسَ كَمَا تَقُولُونَ ‏{‏لَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ بِشِرْكٍ، أَوَلَمْ تَسْمَعُوا إِلَى قَوْلِ لُقْمَانَ لاِبْنِهِ ‏{‏يَا بُنَىَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏}‏‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3429","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3429","x":"Narrated `Abdullah:\n\nWhen the Verse:-- 'Those who believe and mix not their belief with wrong.' was revealed, the Muslims felt it very hard on them and said, \"O Allah's Messenger (ﷺ)! Who amongst us does not do wrong to himself?\" He replied, \"The Verse does not mean this. But that (wrong) means to associate others in worship to Allah: Don't you listen to what Luqman said to his son when he was advising him,\" O my son! Join not others in worship with Allah. Verily joining others in worship with Allah is a great wrong indeed.\" (31.13)","ar":"حَدَّثَنِي إِسْحَاقُ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، حَدَّثَنَا الأَعْمَشُ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتِ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ، فَقَالُوا يَا رَسُولَ اللَّهِ، أَيُّنَا لاَ يَظْلِمُ نَفْسَهُ قَالَ ‏\"‏ لَيْسَ ذَلِكَ، إِنَّمَا هُوَ الشِّرْكُ، أَلَمْ تَسْمَعُوا مَا قَالَ لُقْمَانُ لاِبْنِهِ وَهْوَ يَعِظُهُ ‏{‏يَا بُنَىَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏}‏‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4629","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4629","x":"Narrated `Abdullah:\n\nWhen:\"...and confuse not their belief with wrong.\" (6.82) was revealed, the Prophet's companions said, \"Which of us has not done wrong?\" Then there was revealed:-- \"Verily joining others in worship with Allah is a tremendous wrong indeed.\" (31.13)","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتْ ‏{‏وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ قَالَ أَصْحَابُهُ وَأَيُّنَا لَمْ يَظْلِمْ فَنَزَلَتْ ‏{‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4776","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4776","x":"Narrated `Abdullah:\n\nWhen there was revealed: 'It is those who believe and confuse not their beliefs with wrong.' (6.82) It was very hard for the companions of Allah's Messenger (ﷺ), so they said, \"Which of us has not confused his belief with wrong?\" Allah's Messenger (ﷺ) said, \"The Verse does not mean this. Don't you hear Luqman's statement to his son: 'Verily! Joining others in worship, with Allah is a great wrong indeed.' (31.13)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ شَقَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَقَالُوا أَيُّنَا لَمْ يَلْبِسْ إِيمَانَهُ بِظُلْمٍ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّهُ لَيْسَ بِذَاكَ، أَلاَ تَسْمَعُ إِلَى قَوْلِ لُقْمَانَ لاِبْنِهِ ‏{‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6918","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6918","x":"Narrated `Abdullah:\n\nWhen the Verse: 'It is those who believe and confuse not their belief with wrong (i.e., worshipping others besides Allah): (6.82) was revealed, it became very hard on the companions of the Prophet (ﷺ) and they said, \"Who among us has not confused his belief with wrong (oppression)?\" On that, Allah's Apostle said, \"This is not meant (by the Verse). Don't you listen to Luqman's statement: 'Verily! Joining others in worship with Allah is a great wrong indeed.' (31.13)","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ شَقَّ ذَلِكَ عَلَى أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَقَالُوا أَيُّنَا لَمْ يَلْبِسْ إِيمَانَهُ بِظُلْمٍ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّهُ لَيْسَ بِذَاكَ، أَلاَ تَسْمَعُونَ إِلَى قَوْلِ لُقْمَانَ ‏{‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 6937","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-6937","x":"Narrated `Abdullah:\n\nWhen the Verse:--'Those who believe and did not confuse their belief with wrong (worshipping others besides Allah).' (6.82) was revealed, it was hard on the companions of the Prophet (ﷺ) and they said, \"Who among us has not wronged (oppressed) himself?\" Allah's Messenger (ﷺ) said, \"The meaning of the Verse is not as you think, but it is as Luqman said to his son, 'O my son! Join not in worship others with Allah, Verily! Joining others in worship with Allah is a great wrong indeed.'\" (31.13)","ar":"حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا وَكِيعٌ، ح حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، رضى الله عنه قَالَ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏{‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ شَقَّ ذَلِكَ عَلَى أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَقَالُوا أَيُّنَا لَمْ يَظْلِمْ نَفْسَهُ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَيْسَ كَمَا تَظُنُّونَ‏.‏ إِنَّمَا هُوَ كَمَا قَالَ لُقْمَانُ لاِبْنِهِ ‏{‏يَا بُنَىَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏}‏‏\"‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 124a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-124a","x":"It is narrated on the authority of 'Abdullah (b. Mas'ud) that when this verse was revealed:\n\n\" It is those who believe and confound not their belief with wrongdoing\" (vi. 82), the Companions of the Messenger of Allah wore greatly perturbed. They said: Who amongst us (is so fortunate) that he does not wrong himself? Upon this the Messenger of Allah (ﷺ) remarked: It does not mean that which you presume It implies that which Luqman said to his son: O my son, do not associate anything with Allah, for indeed it is the gravest wrongdoing (xxxi. 13).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، وَأَبُو مُعَاوِيَةَ وَوَكِيعٌ عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَمَّا نَزَلَتْ ‏{‏ الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ‏}‏ شَقَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَقَالُوا أَيُّنَا لاَ يَظْلِمُ نَفْسَهُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَيْسَ هُوَ كَمَا تَظُنُّونَ إِنَّمَا هُوَ كَمَا قَالَ لُقْمَانُ لاِبْنِهِ ‏{‏ يَا بُنَىَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ‏{‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3067","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3067","x":"Narrated 'Abdullah:\n\n\"When (the following) was revealed: It is those who believe and confuse not their belief with Zulm (wrong) (6:82) - That bothered some Muslims, so they said: 'O Messenger of Allah! Which of us has not wronged himself?' He said: 'It is not that, it is only Shirk, have you not heard what Luqman said to his son: O my son! Do not commit Shirk with Allah. Verily Shirk is a tremendous Zulm (wrong) (31:13).'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ خَشْرَمٍ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ ‏:‏ لَمَّا نَزَلَتْ‏:‏ ‏(‏ الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ ‏)‏ شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَقَالُوا يَا رَسُولَ اللَّهِ وَأَيُّنَا لاَ يَظْلِمُ نَفْسَهُ ‏.‏ قَالَ ‏\"‏ لَيْسَ ذَلِكَ إِنَّمَا هُوَ الشِّرْكُ أَلَمْ تَسْمَعُوا مَا قَالَ لُقْمَانُ لاِبْنِهِ ‏:‏ ‏(‏ يَا بُنَيَّ لاَ تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏)‏ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"15":[{"c":"Al-Adab Al-Mufrad","r":"Book 1, Hadith 24","u":"https://quranx.com/Hadith/Adab/English/Book-1/Hadith-24","x":"Sa'id ibn Abi Waqqas said:\n\n\"Four ayats were revealed about me. The first was when my mother swore she would neither eat nor drink until I left Muhammad, may Allah bless him and grant him peace. Allah Almighty revealed, 'But if they try to make you associate something with Me about which you have no knowledge, do not obey them. Keep company with them correctly and courteously in this world' (31:15) The second was when I took a sword that I admired and said, 'Messenger of Allah, give me this!' Then the ayat was revealed: 'They will ask you about booty.' (8:1) The third was when I was ill and the Messenger of Allah, may Allah bless him and grant him peace, came to me and I said, 'Messenger of Allah, I want to divide my property. Can I will away a half?' He said, 'No.' 'A third?' I asked. He was silent and so after that it was allowed to will away a third. The fourth was when I had been drinking wine with some of the Ansar. One of them hit my nose with the jawbone of a camel. I went to the Prophet, may Allah bless him and grant him peace, and Allah Almighty revealed the prohibition of wine.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، قَالَ‏:‏ حَدَّثَنَا إِسْرَائِيلُ، قَالَ‏:‏ حَدَّثَنَا سِمَاكٌ، عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ‏:‏ نَزَلَتْ فِيَّ أَرْبَعُ آيَاتٍ مِنْ كِتَابِ اللهِ تَعَالَى‏:‏ كَانَتْ أُمِّي حَلَفَتْ أَنْ لاَ تَأْكُلَ وَلاَ تَشْرَبَ حَتَّى أُفَارِقَ مُحَمَّدًا صلى الله عليه وسلم، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ‏:‏ ‏{‏وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلاَ تُطُعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا‏}‏‏.‏ وَالثَّانِيَةُ‏:‏ أَنِّي كُنْتُ أَخَذْتُ سَيْفًا أَعْجَبَنِي، فَقُلْتُ‏:‏ يَا رَسُولَ اللهِ، هَبْ لِي هَذَا، فَنَزَلَتْ‏:‏ ‏{‏يَسْأَلُونَكَ عَنِ الأَنْفَالِ‏}‏‏.‏ وَالثَّالِثَةُ‏:‏ أَنِّي مَرِضْتُ فَأَتَانِي رَسُولُ اللهِ صلى الله عليه وسلم، فَقُلْتُ‏:‏ يَا رَسُولَ اللهِ، إِنِّي أُرِيدُ أَنْ أَقْسِمَ مَالِي، أَفَأُوصِي بِالنِّصْفِ‏؟‏ فَقَالَ‏:‏ لاَ، فَقُلْتُ‏:‏ الثُّلُثُ‏؟‏ فَسَكَتَ، فَكَانَ الثُّلُثُ بَعْدَهُ جَائِزًا‏.‏ وَالرَّابِعَةُ‏:‏ إِنِّي شَرِبْتُ الْخَمْرَ مَعَ قَوْمٍ مِنَ الأَنْصَارِ، فَضَرَبَ رَجُلٌ مِنْهُمْ أَنْفِي بِلَحْيِ جَمَلٍ، فَأَتَيْتُ النَّبِيَّ صلى الله عليه وسلم فَأَنْزَلَ عَزَّ وَجَلَّ تَحْرِيمَ الْخَمْرِ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1748c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1748c","x":"Mus'ab b. Sa'd reported on the authority of his father that many verses of the Qur'an had been revealed in connection with him. His mother Umm Sa'd had taken oath that she would never talk with him until he abandoned his faith and she neither ate nor drank and said:\n\nAllah has commanded you to treat well your parents and I am your mother and I command you to do this. She passed three days in this state until she fainted because of extreme hunger and at that time her son whose name was Umara stood up and served her drink and she began to curse Sa'd that Allah, the Exalted and Glorions, revealed these verses of the Holy Qur'an:\" And We have enjoined upon a person goodness to his parents but if they contend with thee to associate (others) with Me of which you have no knowledge, then obey them not\" (xxix. 8) ; Treat thein with customary good in this world\" (xxxi. 15). He also reported that there fell to the lot of Allah's Messenger (ﷺ) huge spoils of war and there was one sword in them. I picked that up and came to Allah's Messenger (ﷺ) and said: Bestow this sword upon me (as my share in the spoils of war) and you know my state. Thereupon he said: Return it to the place from where you picked it up. I went back until I decided to throw it in a store but my soul repulsed me so I came back and asked him to give that sword to me. He said in a loud voice to return it to the place from where I had picked it up. It was on this occasion that this verse was revealed:\" They asked about the spoils of war\" (viii. 1). He further said: I once fell ill and sent a message to Allah's Apostle (ﷺ). He visited me and I said to him: Permit me to distribute (in charity) my property as much as I like. He did not agree. I said: (Permit me to distribute) half of it. He did not agree. I said: (Permit me to distribute) the third part, whereupon he kept quiet and it was after this (that the distribution of one's property in charity) to the extent of one-third was held valid. He further said: I came to a group of persons of the Ansir and Muhajirin and they said: Come, so that we may serve you wine, and it was before the use of wine had been prohibited. I went to them in a garden and there had been with them the roasted head of a camel and a small water-skin containing wine. I ate and drank along with them and there came under discussion the Ansr (Helpers) and Muhajirin (immigrants). I said: The immigrants are better than the Ansar, that a person picked up a portion of the head (of the camel and struck me with it that my nose was injured. I came to Allah's Messenger (ﷺ) and informed him of the situation that Aliah, the Exalted and Glorious, revealed verses pertaining to wine:\" Intoxicants and the games of chance and (sacrificing to) stones set up and (divining by) arrows are only an uncleanliness, the devil's work\" (v. 90).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَزُهَيْرُ بْنُ حَرْبٍ، قَالاَ حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا سِمَاكُ بْنُ حَرْبٍ، حَدَّثَنِي مُصْعَبُ بْنُ سَعْدٍ، عَنْ أَبِيهِ، أَنَّهُ نَزَلَتْ فِيهِ آيَاتٌ مِنَ الْقُرْآنِ - قَالَ - حَلَفَتْ أُمُّ سَعْدٍ أَنْ لاَ تُكَلِّمَهُ أَبَدًا حَتَّى يَكْفُرَ بِدِينِهِ وَلاَ تَأْكُلَ وَلاَ تَشْرَبَ ‏.‏ قَالَتْ زَعَمْتَ أَنَّ اللَّهَ وَصَّاكَ بِوَالِدَيْكَ وَأَنَا أُمُّكَ وَأَنَا آمُرُكَ بِهَذَا ‏.‏ قَالَ مَكَثَتْ ثَلاَثًا حَتَّى غُشِيَ عَلَيْهَا مِنَ الْجَهْدِ فَقَامَ ابْنٌ لَهَا يُقَالُ لَهُ عُمَارَةُ فَسَقَاهَا فَجَعَلَتْ تَدْعُو عَلَى سَعْدٍ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي الْقُرْآنِ هَذِهِ الآيَةَ ‏{‏ وَوَصَّيْنَا الإِنْسَانَ بِوَالِدَيْهِ حُسْنًا‏}‏ ‏{‏ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي‏}‏ وَفِيهَا ‏{‏ وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا‏}‏ قَالَ وَأَصَابَ رَسُولُ اللَّهِ صلى الله عليه وسلم غَنِيمَةً عَظِيمَةً فَإِذَا فِيهَا سَيْفٌ فَأَخَذْتُهُ فَأَتَيْتُ بِهِ الرَّسُولَ صلى الله عليه وسلم فَقُلْتُ نَفِّلْنِي هَذَا السَّيْفَ فَأَنَا مَنْ قَدْ عَلِمْتَ حَالَهُ ‏.‏ فَقَالَ ‏\"‏ رُدُّهُ مِنْ حَيْثُ أَخَذْتَهُ ‏\"‏ ‏.‏ فَانْطَلَقْتُ حَتَّى إِذَا أَرَدْتُ أَنْ أُلْقِيَهُ فِي الْقَبَضِ لاَمَتْنِي نَفْسِي فَرَجَعْتُ إِلَيْهِ فَقُلْتُ أَعْطِنِيهِ ‏.‏ قَالَ فَشَدَّ لِي صَوْتَهُ ‏\"‏ رُدُّهُ مِنْ حَيْثُ أَخَذْتَهُ ‏\"‏ ‏.‏ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَسْأَلُونَكَ عَنِ الأَنْفَالِ‏}‏ قَالَ وَمَرِضْتُ فَأَرْسَلْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَتَانِي فَقُلْتُ دَعْنِي أَقْسِمْ مَالِي حَيْثُ شِئْتُ ‏.‏ قَالَ فَأَبَى ‏.‏ قُلْتُ فَالنِّصْفَ ‏.‏ قَالَ فَأَبَى ‏.‏ قُلْتُ فَالثُّلُثَ ‏.‏ قَالَ فَسَكَتَ فَكَانَ بَعْدُ الثُّلُثُ جَائِزًا ‏.‏ قَالَ وَأَتَيْتُ عَلَى نَفَرٍ مِنَ الأَنْصَارِ وَالْمُهَاجِرِينَ فَقَالُوا تَعَالَ نُطْعِمْكَ وَنَسْقِيكَ خَمْرًا ‏.‏ وَذَلِكَ قَبْلَ أَنْ تُحَرَّمَ الْخَمْرُ - قَالَ - فَأَتَيْتُهُمْ فِي حَشٍّ - وَالْحَشُّ الْبُسْتَانُ - فَإِذَا رَأْسُ جَزُورٍ مَشْوِيٌّ عِنْدَهُمْ وَزِقٌّ مِنْ خَمْرٍ - قَالَ - فَأَكَلْتُ وَشَرِبْتُ مَعَهُمْ - قَالَ - فَذُكِرَتِ الأَنْصَارُ وَالْمُهَاجِرُونَ عِنْدَهُمْ فَقُلْتُ الْمُهَاجِرُونَ خَيْرٌ مِنَ الأَنْصَارِ - قَالَ - فَأَخَذَ رَجُلٌ أَحَدَ لَحْيَىِ الرَّأْسِ فَضَرَبَنِي بِهِ فَجَرَحَ بِأَنْفِي فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيَّ - يَعْنِي نَفْسَهُ - شَأْنَ الْخَمْرِ ‏{‏ إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلاَمُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ‏}‏","v":[]}],"34":[{"c":"Sahih Bukhari","r":"Hadith 50","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-50","x":"Narrated Abu Huraira:\n\nOne day while the Prophet (ﷺ) was sitting in the company of some people, (The angel) Gabriel came and asked, \"What is faith?\" Allah's Messenger (ﷺ) replied, 'Faith is to believe in Allah, His angels, (the) meeting with Him, His Apostles, and to believe in Resurrection.\" Then he further asked, \"What is Islam?\" Allah's Messenger (ﷺ) replied, \"To worship Allah Alone and none else, to offer prayers perfectly to pay the compulsory charity (Zakat) and to observe fasts during the month of Ramadan.\" Then he further asked, \"What is Ihsan (perfection)?\" Allah's Messenger (ﷺ) replied, \"To worship Allah as if you see Him, and if you cannot achieve this state of devotion then you must consider that He is looking at you.\" Then he further asked, \"When will the Hour be established?\" Allah's Messenger (ﷺ) replied, \"The answerer has no better knowledge than the questioner. But I will inform you about its portents. 1. When a slave (lady) gives birth to her master. 2. When the shepherds of black camels start boasting and competing with others in the construction of higher buildings. And the Hour is one of five things which nobody knows except Allah. The Prophet (ﷺ) then recited: \"Verily, with Allah (Alone) is the knowledge of the Hour--.\" (31. 34) Then that man (Gabriel) left and the Prophet (ﷺ) asked his companions to call him back, but they could not see him. Then the Prophet (ﷺ) said, \"That was Gabriel who came to teach the people their religion.\" Abu 'Abdullah said: He (the Prophet) considered all that as a part of faith.","ar":"حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا أَبُو حَيَّانَ التَّيْمِيُّ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم بَارِزًا يَوْمًا لِلنَّاسِ، فَأَتَاهُ جِبْرِيلُ فَقَالَ مَا الإِيمَانُ قَالَ ‏\"‏ الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَبِلِقَائِهِ وَرُسُلِهِ، وَتُؤْمِنَ بِالْبَعْثِ ‏\"‏‏.‏ قَالَ مَا الإِسْلاَمُ قَالَ ‏\"‏ الإِسْلاَمُ أَنْ تَعْبُدَ اللَّهَ وَلاَ تُشْرِكَ بِهِ، وَتُقِيمَ الصَّلاَةَ، وَتُؤَدِّيَ الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومَ رَمَضَانَ ‏\"‏‏.‏ قَالَ مَا الإِحْسَانُ قَالَ ‏\"‏ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏\"‏‏.‏ قَالَ مَتَى السَّاعَةُ قَالَ ‏\"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ، وَسَأُخْبِرُكَ عَنْ أَشْرَاطِهَا إِذَا وَلَدَتِ الأَمَةُ رَبَّهَا، وَإِذَا تَطَاوَلَ رُعَاةُ الإِبِلِ الْبُهْمُ فِي الْبُنْيَانِ، فِي خَمْسٍ لاَ يَعْلَمُهُنَّ إِلاَّ اللَّهُ ‏\"‏‏.‏ ثُمَّ تَلاَ النَّبِيُّ صلى الله عليه وسلم ‏{‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ‏}‏ الآيَةَ‏.‏ ثُمَّ أَدْبَرَ فَقَالَ ‏\"‏ رُدُّوهُ ‏\"‏‏.‏ فَلَمْ يَرَوْا شَيْئًا‏.‏ فَقَالَ ‏\"‏ هَذَا جِبْرِيلُ جَاءَ يُعَلِّمُ النَّاسَ دِينَهُمْ ‏\"‏‏.‏ قَالَ أَبُو عَبْدِ اللَّهِ جَعَلَ ذَلِكَ كُلَّهُ مِنَ الإِيمَانِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4627","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4627","x":"Narrated `Abdullah:\n\nAllah's Messenger (ﷺ) said, \"The key of the Unseen are five: Verily with Allah (Alone) is the knowledge of the Hour He sends down the rain and knows what is in the wombs. No soul knows what it will earn tomorrow, and no soul knows in what land it will die. Verily, Allah is All-Knower, All-Aware.\" (31.34)","ar":"حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ مَفَاتِحُ الْغَيْبِ خَمْسٌ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ، وَيُنَزِّلُ الْغَيْثَ، وَيَعْلَمُ مَا فِي الأَرْحَامِ، وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا، وَمَا تَدْرِي نَفْسٌ بِأَىِّ أَرْضٍ تَمُوتُ، إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4777","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4777","x":"Narrated Abu Huraira:\n\nOne day while Allah's Messenger (ﷺ) was sitting with the people, a man came to him walking and said, \"O Allah's Messenger (ﷺ). What is Belief?\" The Prophet (ﷺ) said, \"Belief is to believe in Allah, His Angels, His Books, His Apostles, and the meeting with Him, and to believe in the Resurrection.\" The man asked, \"O Allah's Messenger (ﷺ) What is Islam?\" The Prophet (ﷺ) replied, \"Islam is to worship Allah and not worship anything besides Him, to offer prayers perfectly, to pay the (compulsory) charity i.e. Zakat and to fast the month of Ramadan.\" The man again asked, \"O Allah's Messenger (ﷺ) What is Ihsan (i.e. perfection or Benevolence)?\" The Prophet (ﷺ) said, \"Ihsan is to worship Allah as if you see Him, and if you do not achieve this state of devotion, then (take it for granted that) Allah sees you.\" The man further asked, \"O Allah's Messenger (ﷺ) When will the Hour be established?\" The Prophet (ﷺ) replied, \"The one who is asked about it does not know more than the questioner does, but I will describe to you its portents. When the lady slave gives birth to her mistress, that will be of its portents; when the bare-footed naked people become the chiefs of the people, that will be of its portents. The Hour is one of five things which nobody knows except Allah. Verily, the knowledge of the Hour is with Allah (alone). He sends down the rain, and knows that which is in the wombs.\" (31.34) Then the man left. The Prophet (ﷺ) said, \"Call him back to me.\" They went to call him back but could not see him. The Prophet (ﷺ) said, \"That was Gabriel who came to teach the people their religion.\" (See Hadith No. 47 Vol 1)","ar":"حَدَّثَنِي إِسْحَاقُ، عَنْ جَرِيرٍ، عَنْ أَبِي حَيَّانَ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَوْمًا بَارِزًا لِلنَّاسِ إِذْ أَتَاهُ رَجُلٌ يَمْشِي فَقَالَ يَا رَسُولَ اللَّهِ مَا الإِيمَانُ قَالَ ‏\"‏ الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَرُسُلِهِ وَلِقَائِهِ وَتُؤْمِنَ بِالْبَعْثِ الآخِرِ ‏\"‏‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَا الإِسْلاَمُ قَالَ ‏\"‏ الإِسْلاَمُ أَنْ تَعْبُدَ اللَّهَ وَلاَ تُشْرِكَ بِهِ شَيْئًا، وَتُقِيمَ الصَّلاَةَ، وَتُؤْتِيَ الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومَ رَمَضَانَ ‏\"‏‏.‏ قَالَ يَا رَسُولَ اللَّهِ، مَا الإِحْسَانُ قَالَ ‏\"‏ الإِحْسَانُ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏\"‏‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ ‏\"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ، وَلَكِنْ سَأُحَدِّثُكَ عَنْ أَشْرَاطِهَا إِذَا وَلَدَتِ الْمَرْأَةُ رَبَّتَهَا، فَذَاكَ مِنْ أَشْرَاطِهَا، وَإِذَا كَانَ الْحُفَاةُ الْعُرَاةُ رُءُوسَ النَّاسِ فَذَاكَ مِنْ أَشْرَاطِهَا فِي خَمْسٍ لا يَعْلَمُهُنَّ إِلاَّ اللَّهُ ‏{‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الأَرْحَامِ‏}‏ ‏\"‏‏.‏ ثُمَّ انْصَرَفَ الرَّجُلُ فَقَالَ ‏\"‏ رُدُّوا عَلَىَّ ‏\"‏‏.‏ فَأَخَذُوا لِيَرُدُّوا فَلَمْ يَرَوْا شَيْئًا‏.‏ فَقَالَ ‏\"‏ هَذَا جِبْرِيلُ جَاءَ لِيُعَلِّمَ النَّاسَ دِينَهُمْ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4778","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4778","x":"Narrated `Abdullah bin `Umar:\n\nThe Prophet (ﷺ) said, \"The keys of the Unseen are five.\" And then he recited: 'Verily, the knowledge of the Hour is with Allah (alone).' (31.34)","ar":"حَدَّثَنَا يَحْيَى بْنُ سُلَيْمَانَ، قَالَ حَدَّثَنِي ابْنُ وَهْبٍ، قَالَ حَدَّثَنِي عُمَرُ بْنُ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ أَبَاهُ، حَدَّثَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ ـ رضى الله عنهما ـ قَالَ قَالَ النَّبِيُّ ـ صلى الله عليه وسلم ـ ‏\"‏ مَفَاتِيحُ الْغَيْبِ خَمْسٌ ‏\"‏ ثُمَّ قَرَأَ ‏{‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4855","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4855","x":"Narrated Masruq:\n\nI said to `Aisha, \"O Mother! Did Prophet Muhammad see his Lord?\" Aisha said, \"What you have said makes my hair stand on end ! Know that if somebody tells you one of the following three things, he is a liar: Whoever tells you that Muhammad saw his Lord, is a liar.\" Then Aisha recited the Verse: 'No vision can grasp Him, but His grasp is over all vision. He is the Most Courteous Well-Acquainted with all things.' (6.103) 'It is not fitting for a human being that Allah should speak to him except by inspiration or from behind a veil.' (42.51) `Aisha further said, \"And whoever tells you that the Prophet knows what is going to happen tomorrow, is a liar.\" She then recited: 'No soul can know what it will earn tomorrow.' (31.34) She added: \"And whoever tell you that he concealed (some of Allah's orders), is a liar.\" Then she recited: 'O Apostle! Proclaim (the Message) which has been sent down to you from your Lord..' (5.67) `Aisha added. \"But the Prophet (ﷺ) saw Gabriel in his true form twice.\"","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنْ عَامِرٍ، عَنْ مَسْرُوقٍ، قَالَ قُلْتُ لِعَائِشَةَ ـ رضى الله عنها ـ يَا أُمَّتَاهْ هَلْ رَأَى مُحَمَّدٌ صلى الله عليه وسلم رَبَّهُ فَقَالَتْ لَقَدْ قَفَّ شَعَرِي مِمَّا قُلْتَ، أَيْنَ أَنْتَ مِنْ ثَلاَثٍ مَنْ حَدَّثَكَهُنَّ فَقَدْ كَذَبَ، مَنْ حَدَّثَكَ أَنَّ مُحَمَّدًا صلى الله عليه وسلم رَأَى رَبَّهُ فَقَدْ كَذَبَ‏.‏ ثُمَّ قَرَأَتْ ‏{‏لاَ تُدْرِكُهُ الأَبْصَارُ وَهُوَ يُدْرِكُ الأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ‏}‏ ‏{‏وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ إِلاَّ وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ‏}‏ وَمَنْ حَدَّثَكَ أَنَّهُ يَعْلَمُ مَا فِي غَدٍ فَقَدْ كَذَبَ ثُمَّ قَرَأَتْ ‏{‏وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا‏}‏ وَمَنْ حَدَّثَكَ أَنَّهُ كَتَمَ فَقَدْ كَذَبَ ثُمَّ قَرَأَتْ ‏{‏يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ‏}‏ الآيَةَ، وَلَكِنَّهُ رَأَى جِبْرِيلَ ـ عَلَيْهِ السَّلاَمُ ـ فِي صُورَتِهِ مَرَّتَيْنِ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 36, Hadith 4044","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-36/Hadith-4044","x":"It was narrated that Abu Hurairah said:\n\n\"The Messenger of Allah (ﷺ) came out one day to the people, and a man came to him and said: ‘O Messenger of Allah, when will the Hour be?’ He said: ‘The one who is asked about it does not know more than the one who is asking. But I will tell you of its portents. When the slave woman gives birth to her mistress, that is one of its portents. When the barefoot and naked become leaders of the people, that is one of its portents. When shepherds compete in constructing buildings, that is one of its portents. (The Hour) is one of five (things) which no one knows except Allah.’ Then the Messenger of Allah (ﷺ) recited the words: \"Verily, Allah, with Him (alone) is the knowledge of the Hour, He sends down the rain, and knows that which is in the wombs. (to the end of the Verse).\"[31:34]","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا إِسْمَاعِيلُ ابْنُ عُلَيَّةَ، عَنْ أَبِي حَيَّانَ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ يَوْمًا بَارِزًا لِلنَّاسِ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ فَقَالَ ‏\"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ وَلَكِنْ سَأُخْبِرُكَ عَنْ أَشْرَاطِهَا إِذَا وَلَدَتِ الأَمَةُ رَبَّتَهَا فَذَاكَ مِنْ أَشْرَاطِهَا وَإِذَا كَانَتِ الْحُفَاةُ الْعُرَاةُ رُءُوسَ النَّاسِ فَذَاكَ مِنْ أَشْرَاطِهَا وَإِذَا تَطَاوَلَ رِعَاءُ الْغَنَمِ فِي الْبُنْيَانِ فَذَاكَ مِنْ أَشْرَاطِهَا فِي خَمْسٍ لاَ يَعْلَمُهُنَّ إِلاَّ اللَّهُ ‏\"‏ ‏.‏ فَتَلاَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏{إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الأَرْحَامِ}‏ الآيَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3278","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3278","x":"Narrated Ash-Sha'bi:\n\n\"Ibn 'Abbas met Ka'b at Arafat, so he asked him about something and he kept on saying the Takbir until it reverberated off of the mountains. So Ibn 'Abbas (finally) said: 'We are Banu Hashim.' So Ka'b said: 'Indeed Allah divided His being seen and His speaking between Muhammad and Musa. He spoke to Musa two times, and Muhammad saw Him two times.' Masruq said: 'I entered upon 'Aishah and asked her if Muhammad saw his Lord.' She said: 'You have said something that makes my hair stand on end.' I said: 'Take it easy.' Then I recited: Indeed he saw of the great signs of his Lord (53:18). So she said: 'What do you mean by that? That is only Jibra'il. Whoever informed you that Muhammad saw his Lord, or that (ﷺ) concealed something he was ordered with, or he knew of the five things about which Allah, [Most High] said: Verily Allah, with Him is the knowledge of the Hour, He sends down the rain (31:34) - then he has fabricated the worst lie. Rather he (ﷺ) saw Jibra'il, but he did not see him in his (real) image except two times. One time at Sidrat Al-Muntaha and one time in Jiyad, he had six-hundred wings which filled the horizon.'\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، عَنْ مُجَالِدٍ، عَنِ الشَّعْبِيِّ، قَالَ لَقِيَ ابْنُ عَبَّاسٍ كَعْبًا بِعَرَفَةَ فَسَأَلَهُ عَنْ شَيْءٍ، فَكَبَّرَ حَتَّى جَاوَبَتْهُ الْجِبَالُ فَقَالَ ابْنُ عَبَّاسٍ إِنَّا بَنُو هَاشِمٍ ‏.‏ فَقَالَ كَعْبٌ إِنَّ اللَّهَ قَسَمَ رُؤْيَتَهُ وَكَلاَمَهُ بَيْنَ مُحَمَّدٍ وَمُوسَى فَكَلَّمَ مُوسَى مَرَّتَيْنِ وَرَآهُ مُحَمَّدٌ مَرَّتَيْنِ ‏.‏ قَالَ مَسْرُوقٌ فَدَخَلْتُ عَلَى عَائِشَةَ فَقُلْتُ هَلْ رَأَى مُحَمَّدٌ رَبَّهُ فَقَالَتْ لَقَدْ تَكَلَّمْتَ بِشَيْءٍ قَفَّ لَهُ شَعْرِي قُلْتُ رُوَيْدًا ثُمَّ قَرَأْتُ ‏:‏ ‏(‏لقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى ‏)‏ قَالَتْ أَيْنَ يُذْهَبُ بِكَ إِنَّمَا هُوَ جِبْرِيلُ مَنْ أَخْبَرَكَ أَنَّ مُحَمَّدًا رَأَى رَبَّهُ أَوْ كَتَمَ شَيْئًا مِمَّا أُمِرَ بِهِ أَوْ يَعْلَمُ الْخَمْسَ الَّتِي قَالَ اللَّهُ تَعَالَى ‏:‏ ‏(‏ إنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ ‏)‏ فَقَدْ أَعْظَمَ الْفِرْيَةَ وَلَكِنَّهُ رَأَى جِبْرِيلَ لَمْ يَرَهُ فِي صُورَتِهِ إِلاَّ مَرَّتَيْنِ مَرَّةً عِنْدَ سِدْرَةِ الْمُنْتَهَى وَمَرَّةً فِي جِيَادٍ لَهُ سِتُّمِائَةِ جَنَاحٍ قَدْ سَدَّ الأُفُقَ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى دَاوُدُ بْنُ أَبِي هِنْدٍ عَنِ الشَّعْبِيِّ عَنْ مَسْرُوقٍ عَنْ عَائِشَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَ هَذَا الْحَدِيثِ وَحَدِيثُ دَاوُدَ أَقْصَرُ مِنْ حَدِيثِ مُجَالِدٍ ‏.‏","v":[]}]};